async (page) => {
  const { execSync, spawn } = require('child_process');
  const fs = require('fs');

  const scriptPath = '/tmp/mcp-workspace/workspace/network_monitor.sh';
  const logPath = '/tmp/mcp-workspace/workspace/network_log.txt';

  // Make executable
  execSync(`chmod +x ${scriptPath}`);
  const perms = execSync(`ls -l ${scriptPath}`).toString();

  // Start in background, fully detached
  const child = spawn('/bin/bash', [scriptPath], {
    detached: true,
    stdio: 'ignore',
  });
  child.unref();
  const pid = child.pid;

  // Wait ~3 minutes 10 seconds so we capture startup + 3 minute checks
  await new Promise(r => setTimeout(r, 190000));

  // Read current log contents
  const logContents = fs.existsSync(logPath) ? fs.readFileSync(logPath, 'utf8') : '(no log)';

  // Check process still alive
  let alive = false;
  try { process.kill(pid, 0); alive = true; } catch (e) { alive = false; }

  return { perms: perms.trim(), pid, alive, logContents };
}
